mapper.update:
update article
icon = #{icon}, title = #{title}, content = #{content}, sort = #{sort}, status = #{status}, category_id = #{categoryId}, update_time = #{updateTime}
where id = #{id}

mapper.select:
select a.id as id, a.user_id as userId, a.icon as icon, a.title as title, a.create_time as createTiem, u.nickname as userNickname from article a left join user u on a.user_id = u.id
and a.category_id = #{categoryId} and a.title like concat('%', #{title}, '%') and a.create_time > #{createTime} and u.nickname like concat('%', #{userNickname}, '%') and a.status = #{status}
order by a.create_time desc
